@Composable fun PowerPointReaderScreen(onBack:()->Unit,vm:PowerPointReaderViewModel=hiltViewModel()){
 val s by vm.state.collectAsStateWithLifecycle();var web by remember{mutableStateOf<WebView?>(null)};var search by remember{mutableStateOf(false)};var query by remember{mutableStateOf("")};var current by remember{mutableIntStateOf(0)};var total by remember{mutableIntStateOf(0)};var slide by remember{mutableIntStateOf(0)};var slides by remember{mutableIntStateOf(0)};val access=rememberStorageAccessRequest(vm::onResume)
 BackHandler(search){search=false;query="";web?.evaluateJavascript("pptxControl.clear()",null)}
 LaunchedEffect(query,search,s.phase){if(search&&s.phase==PptxPhase.Ready){kotlinx.coroutines.delay(250);Log.d(PowerPointReaderViewModel.TAG,"search command queryLength=${query.length}");web?.evaluateJavascript("pptxControl.search(${JSONObject.quote(query)})",null)}}
 Scaffold(Modifier.fillMaxSize(),topBar={if(search)TopAppBar(title={TextField(query,{query=it},singleLine=true,placeholder={Text("Search slides")},supportingText={if(query.isNotEmpty())Text(if(total==0)"No matches" else "$current of $total")})},navigationIcon={IconButton(onClick={search=false;query="";web?.evaluateJavascript("pptxControl.clear()",null)}){Icon(Icons.Default.Close,"Close search")}},actions={IconButton(enabled=total>0,onClick={web?.evaluateJavascript("pptxControl.previous()",null)}){Icon(Icons.Default.KeyboardArrowUp,"Previous")};IconButton(enabled=total>0,onClick={web?.evaluateJavascript("pptxControl.next()",null)}){Icon(Icons.Default.KeyboardArrowDown,"Next")}}) else TopAppBar(title={Text(s.fileName?:"PowerPoint Reader",maxLines=1,overflow=TextOverflow.Ellipsis)},navigationIcon={IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")}},actions={if(s.phase==PptxPhase.Ready){Text("$slide/$slides",style=MaterialTheme.typography.labelLarge);IconButton(onClick={web?.evaluateJavascript("pptxControl.fit()",null)}){Icon(Icons.Outlined.FitScreen,"Fit")};IconButton(onClick={search=true}){Icon(Icons.Default.Search,"Search")}}})}){pad->Column(Modifier.fillMaxSize().padding(pad)){val ready=s.ready;if(ready!=null&&s.phase in setOf(PptxPhase.Preparing,PptxPhase.Rendering,PptxPhase.Ready))PptxWeb(ready,Modifier.fillMaxWidth().weight(1f),{web=it}){p,sl,ss,c,t->slide=sl;slides=ss;current=c;total=t;vm.viewerPhase(p)} else if(s.phase in setOf(PptxPhase.Resolving,PptxPhase.Validating))Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){CircularProgressIndicator();Text(if(s.phase==PptxPhase.Validating)"Checking presentation…" else "Opening presentation…")}} else ErrorMessage(s.phase,onBack,if(s.phase==PptxPhase.PermissionDenied)access else vm::retry)}}
}
private fun parse(raw:String,cb:(Int,Int,Int,Int)->Unit)=runCatching{val o=JSONObject(JSONArray("[$raw]").getString(0));val count=o.optInt("matchCount");val index=o.optInt("activeMatchIndex",-1);Log.d(PowerPointReaderViewModel.TAG,"search status queryLength=${o.optString("query").length} matches=$count active=$index error=${o.optString("searchErrorCode")}");cb(if(index>=0)index+1 else 0,count,o.optInt("slide",1),o.optInt("slides"))}
@Composable private fun ErrorMessage(p:PptxPhase,back:()->Unit,retry:()->Unit){val msg=when(p){PptxPhase.LegacyUnsupported->"This older PowerPoint format is not supported yet. Please save it as a .pptx file and try again.";PptxPhase.MacroUnsupported->"This PowerPoint format is unsupported. Macros are never executed.";PptxPhase.Encrypted->"Password-protected or encrypted presentations are not supported.";PptxPhase.Corrupt->"This presentation is damaged or is not a valid PPTX file.";PptxPhase.SafetyLimit->"This presentation exceeds safe processing limits.";PptxPhase.Missing->"This presentation may have been moved or deleted.";PptxPhase.PermissionDenied->"Access to this presentation is no longer available.";PptxPhase.RenderTimeout->"The presentation took too long to render.";PptxPhase.RendererCrash->"The presentation renderer stopped.";else->"The presentation could not be opened."};Column(Modifier.fillMaxSize().padding(32.dp),Arrangement.Center,Alignment.CenterHorizontally){Text(msg);Row{TextButton(onClick=back){Text("Back")};Button(onClick=retry){Text("Try again")}}}}
@SuppressLint("SetJavaScriptEnabled") @Composable private fun PptxWeb(r:PptxReady,mod:Modifier,onWeb:(WebView?)->Unit,onPhase:(PptxPhase,Int,Int,Int,Int)->Unit){val ctx=LocalContext.current;val active=remember(r.token){AtomicBoolean(true)};val loader=remember(r.token){WebViewAssetLoader.Builder().addPathHandler("/assets/pptx_viewer/"){path->if(path in setOf("viewer.html","viewer.css","viewer.js","viewer-state.js","aiden0z-pptx-renderer.browser.es.js")) runCatching{WebResourceResponse(if(path.endsWith(".js")) "text/javascript" else if(path.endsWith(".css")) "text/css" else "text/html","UTF-8",ctx.assets.open("pptx_viewer/$path"))}.getOrNull() else null}.addPathHandler("/presentation/${r.token}/"){path->if(path=="document.pptx"&&r.file.isFile)WebResourceResponse(PowerPointReaderViewModel.PPTX_MIME,null,r.file.inputStream())else null}.build()};AndroidView(modifier=mod,factory={WebView(it).apply{layoutParams=android.view.ViewGroup.LayoutParams(-1,-1);setBackgroundColor(Color.rgb(231,233,236));WebView.setWebContentsDebuggingEnabled(false);settings.apply{javaScriptEnabled=true;javaScriptCanOpenWindowsAutomatically=false;allowFileAccess=false;allowContentAccess=false;allowFileAccessFromFileURLs=false;allowUniversalAccessFromFileURLs=false;setSupportMultipleWindows(false);mixedContentMode=WebSettings.MIXED_CONTENT_NEVER_ALLOW;blockNetworkLoads=true;databaseEnabled=false;domStorageEnabled=false;setGeolocationEnabled(false);saveFormData=false;cacheMode=WebSettings.LOAD_NO_CACHE;builtInZoomControls=true;displayZoomControls=false;setSupportZoom(true);safeBrowsingEnabled=true};webChromeClient=object:WebChromeClient(){override fun onConsoleMessage(m:ConsoleMessage):Boolean{Log.w(PowerPointReaderViewModel.TAG,"js ${m.messageLevel()} line=${m.lineNumber()}");return true};override fun onShowFileChooser(w:WebView?,c:ValueCallback<Array<Uri>>?,p:FileChooserParams?):Boolean{c?.onReceiveValue(null);return true}};setDownloadListener{_,_,_,_,_->};val started=SystemClock.uptimeMillis();var rendered=false;fun poll(){if(!active.get())return;if(!rendered&&SystemClock.uptimeMillis()-started>45_000){onPhase(PptxPhase.RenderTimeout,0,0,0,0);stopLoading();return};evaluateJavascript("pptxControl.status()"){raw->runCatching{val o=JSONObject(JSONArray("[$raw]").getString(0));when(o.getString("status")){"ready"->{rendered=true;parse(raw){c,t,sl,ss->onPhase(PptxPhase.Ready,sl.coerceAtLeast(1),ss,c,t)};Handler(Looper.getMainLooper()).postDelayed({poll()},200)};"error"->onPhase(PptxPhase.Failure,0,0,0,0);else->Handler(Looper.getMainLooper()).postDelayed({poll()},250)}}.onFailure{Handler(Looper.getMainLooper()).postDelayed({poll()},250)}}};webViewClient=object:WebViewClient(){override fun shouldInterceptRequest(v:WebView,q:WebResourceRequest):WebResourceResponse{if(q.url.scheme!="https"||q.url.host!="appassets.androidplatform.net"){Log.w(PowerPointReaderViewModel.TAG,"blocked external request");return blocked()};return loader.shouldInterceptRequest(q.url)?:blocked()};override fun shouldOverrideUrlLoading(v:WebView,q:WebResourceRequest)=true;override fun onPageFinished(v:WebView,u:String){onPhase(PptxPhase.Rendering,0,0,0,0);poll()};override fun onRenderProcessGone(v:WebView,d:RenderProcessGoneDetail):Boolean{Log.e(PowerPointReaderViewModel.TAG,"renderer terminated");onPhase(PptxPhase.RendererCrash,0,0,0,0);v.destroy();return true}};loadUrl("https://appassets.androidplatform.net/assets/pptx_viewer/viewer.html?session=${r.token}");onWeb(this)}},update={onWeb(it)},onRelease={active.set(false);it.evaluateJavascript("pptxControl.destroy()",null);it.stopLoading();it.loadUrl("about:blank");(it.parent as? android.view.ViewGroup)?.removeView(it);it.removeAllViews();it.destroy();onWeb(null)})}
private fun blocked()=WebResourceResponse("text/plain","UTF-8",403,"Blocked",emptyMap(),byteArrayOf().inputStream())
